   266	function renderBulkBar(matched){
   267	  const bar=$("#bulkBar");
   268	  if(selected.size===0){ bar.style.display='none'; bar.innerHTML=''; return; }
   269	  bar.style.display=''; const inArch=locationFilter==='archived';
   270	  bar.innerHTML='<span class="bulkcount">'+selected.size+' selected</span>'
   271	    +(selected.size<matched.length?'<button class="secondary" id="selAll">Select all '+matched.length+' matching</button>':'')
   272	    +'<button class="secondary" id="bAddTag">Add tag…</button><button class="secondary" id="bDelTag">Remove tag…</button>'
   273	    +'<button class="secondary" id="bRead">Mark read</button><button class="secondary" id="bUnread">Mark unread</button>'
   274	    +(inArch?'<button class="secondary" id="bRestore">Restore</button>':'<button class="secondary" id="bArchive">Archive</button>')
   275	    +'<button class="secondary" id="bDelete" style="color:#b91c1c">Delete</button>'
   276	    +'<button class="secondary" id="bClear" style="margin-left:auto">Clear selection</button>';
   277	  const ids=()=>[...selected];
   278	  async function run(action,payload){ const n=selected.size; await api('POST','/api/bulk',{action,ids:ids(),payload}); selected.clear(); await refresh(); render(); return n; }
   279	  const s=(id,fn)=>{ const el=document.getElementById(id); if(el) el.onclick=fn; };
   280	  s('selAll',()=>{ matched.forEach(b=>selected.add(b.id)); render(); });
   281	  s('bClear',()=>{ selected.clear(); render(); });
   282	  s('bRead',async()=>{ const n=await run('read'); flash('Marked '+n+' as read.'); });
   283	  s('bUnread',async()=>{ const n=await run('unread'); flash('Marked '+n+' as unread.'); });
   284	  s('bArchive',async()=>{ const n=await run('archive'); flash('Archived '+n+' bookmarks.'); });
   285	  s('bRestore',async()=>{ const n=await run('restore'); flash('Restored '+n+' bookmarks.'); });
   286	  s('bAddTag',()=>openTagPicker('add'));
   287	  s('bDelTag',()=>openTagPicker('remove'));
   288	  s('bDelete',async()=>{ const n=selected.size; if(!confirm('Permanently delete '+n+' bookmarks?\nThis cannot be undone (and removes their saved copies).')) return; await run('delete'); flash('Permanently deleted '+n+' bookmarks.'); });
   289	}
   290	function openTagPicker(mode){
   291	  const count=selected.size; if(!count) return;
   292	  const selB=()=>state.bookmarks.filter(b=>selected.has(b.id));
   293	  const candidates= mode==='add'? allTags() : [...new Set(selB().flatMap(b=>b.tags||[]))].sort();
   294	  const ov=document.createElement('div'); ov.className='overlay';
   295	  ov.innerHTML='<div class="modal"><h3>'+(mode==='add'?'Add tag to ':'Remove tag from ')+count+' bookmark'+(count>1?'s':'')+'</h3>'
   296	    +'<input type="text" id="tpSearch" placeholder="'+(mode==='add'?'Search or type a new tag…':'Search tags on selected…')+'"><div id="tpList" class="tplist"></div>'
   297	    +'<div class="row" style="justify-content:flex-end;margin-top:10px"><button class="secondary" id="tpCancel">Cancel</button></div></div>';
   298	  document.body.appendChild(ov); const close=()=>ov.remove(); ov.addEventListener('click',e=>{ if(e.target===ov) close(); });
   299	  $("#tpCancel").onclick=close; const search=$("#tpSearch"), listEl=$("#tpList");
   300	  async function apply(tag){ await api('POST','/api/bulk',{action:mode==='add'?'addTag':'removeTag',ids:[...selected],payload:{tag}});
   301	    const c=count; selected.clear(); close(); await refresh(); flash((mode==='add'?'Added tag "':'Removed tag "')+tag+'" '+(mode==='add'?'to ':'from ')+c+' bookmarks.'); render(); }
   302	  function draw(){ const qq=search.value.trim().toLowerCase(); let cs=candidates.filter(t=> qq===''||t.toLowerCase().includes(qq));
   303	    let html=cs.map(t=>'<button type="button" class="tpItem" data-t="'+escAttr(t)+'">'+escHtml(t)+'</button>').join('');
   304	    if(mode==='add'&&qq&&!candidates.some(t=>t.toLowerCase()===qq)) html+='<button type="button" class="tpItem tpnew" data-t="'+escAttr(search.value.trim())+'">+ Create new tag: “'+escHtml(search.value.trim())+'”</button>';
   305	    if(!html) html='<div class="hint" style="padding:8px">'+(mode==='add'?'No existing tags yet. Type to create one.':'The selected bookmarks have no tags to remove.')+'</div>';
   306	    listEl.innerHTML=html; listEl.querySelectorAll('.tpItem').forEach(el=>el.onclick=()=>apply(el.dataset.t)); }
   307	  search.addEventListener('input',draw); draw(); search.focus();
