   319	function makeMultiTag(wrap, chosen){
   320	  function draw(){ wrap.innerHTML=[...chosen].map(t=>'<span class="mtchip">'+escHtml(t)+'<button type="button" data-t="'+escAttr(t)+'">×</button></span>').join('')+'<input type="text" class="mtinput" placeholder="type to search tags…">';
   321	    const inp=wrap.querySelector('.mtinput'); const drop=document.createElement('div'); drop.className='mtdrop'; wrap.appendChild(drop);
